CREATE DATABASE IF NOT EXISTS smart_parking;
USE smart_parking;
CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('DRIVER','ADMIN','PARKING_OPERATOR') NOT NULL DEFAULT 'DRIVER', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parking_locations (id CHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, address VARCHAR(255) NOT NULL, area VARCHAR(100) NOT NULL, latitude DECIMAL(10,7), longitude DECIMAL(10,7), price_per_hour DECIMAL(8,2) NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS parking_slots (id CHAR(36) PRIMARY KEY, location_id CHAR(36) NOT NULL, label VARCHAR(30) NOT NULL, status ENUM('AVAILABLE','OCCUPIED','RESERVED','MAINTENANCE') DEFAULT 'AVAILABLE', vehicle_type VARCHAR(30) DEFAULT 'CAR', FOREIGN KEY(location_id) REFERENCES parking_locations(id), UNIQUE(location_id,label), INDEX(status));
CREATE TABLE IF NOT EXISTS reservations (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, slot_id CHAR(36) NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, status ENUM('CONFIRMED','CANCELLED','COMPLETED') DEFAULT 'CONFIRMED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(slot_id) REFERENCES parking_slots(id), INDEX(slot_id,start_time,end_time));
CREATE TABLE IF NOT EXISTS traffic_records (id BIGINT AUTO_INCREMENT PRIMARY KEY, area VARCHAR(100) NOT NULL, congestion_level ENUM('LOW','MEDIUM','HIGH','SEVERE') NOT NULL, average_speed DECIMAL(6,2), incidents INT DEFAULT 0, recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(area,recorded_at));
CREATE TABLE IF NOT EXISTS parking_predictions (id BIGINT AUTO_INCREMENT PRIMARY KEY, location_id CHAR(36), predicted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, predicted_occupancy DECIMAL(5,2), predicted_available INT, model_version VARCHAR(50));
CREATE TABLE IF NOT EXISTS traffic_predictions (id BIGINT AUTO_INCREMENT PRIMARY KEY, area VARCHAR(100), predicted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, congestion_level VARCHAR(30), confidence DECIMAL(5,2), model_version VARCHAR(50));
CREATE TABLE IF NOT EXISTS notifications (id CHAR(36) PRIMARY KEY, user_id CHAR(36), title VARCHAR(160), message TEXT, read_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id CHAR(36), action VARCHAR(100), entity_type VARCHAR(80), entity_id CHAR(36), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
